def psErasureLocalNameWithFuel (scope : PsErasureScope) (base : String) (fuel : Nat) : Nat -> String :=
  match fuel with
  | Nat.zero => fun (index : Nat) => String.Internal.append base (String.Internal.append "$" (psNatToString index))
  | Nat.succ remaining =>
      let smaller : Nat -> String := psErasureLocalNameWithFuel scope base remaining;
      fun (index : Nat) =>
        let candidate := String.Internal.append base (String.Internal.append "$" (psNatToString index));
        if psErasureLocalNameUsed scope candidate then smaller (Nat.succ index) else candidate

def psErasureEtaNameWithFuel
    (body : PsVerifiedIrExpr) (used : List PsVerifiedIrParameter) (fuel : Nat) : Nat -> Except PsErasureError String :=
  match fuel with
  | Nat.zero => fun (_index : Nat) => Except.error PsErasureError.fuelExhausted
  | Nat.succ remaining =>
      let smaller : Nat -> Except PsErasureError String := psErasureEtaNameWithFuel body used remaining;
      fun (index : Nat) =>
        let candidate := String.Internal.append "__ps_eta_" (psNatToString index);
        let sameName : PsVerifiedIrParameter -> Bool := fun (parameter : PsVerifiedIrParameter) => psStringEq parameter.name candidate;
        if psListAny sameName used then smaller (Nat.succ index)
        else if psErasureIrUsesNameWithFuel 4096 body candidate then smaller (Nat.succ index)
        else Except.ok candidate

def psTsFreshMatchTempWorker (expr : PsVerifiedIrExpr) (attempts : Nat) : Nat -> String :=
  match attempts with
  | Nat.zero => fun (_index : Nat) => "__ps$match$overflow"
  | Nat.succ remaining =>
      let smaller : Nat -> String := psTsFreshMatchTempWorker expr remaining;
      fun (index : Nat) =>
        let candidate := String.Internal.append "__ps$match$" (psNatToString index);
        if psTsExprUsesNameWithFuel 4096 expr candidate then smaller (Nat.succ index) else candidate

def psTsFreshInternalWorker (used : List String) (namePrefix : String) (attempts : Nat) :
    Nat -> PsTsFreshNameResult :=
  match attempts with
  | Nat.zero => fun (index : Nat) => PsTsFreshNameResult.mk (String.Internal.append namePrefix "overflow") (Nat.succ index)
  | Nat.succ remaining =>
      let smaller : Nat -> PsTsFreshNameResult := psTsFreshInternalWorker used namePrefix remaining;
      fun (index : Nat) =>
        let candidate := String.Internal.append namePrefix (psNatToString index);
        let sameName : String -> Bool := fun (name : String) => psStringEq name candidate;
        if psListAny sameName used then smaller (Nat.succ index)
        else PsTsFreshNameResult.mk candidate (Nat.succ index)

def psTsBuildSymbolMap (namePrefix : String) (names : List String) : PsTsSymbolMapState -> PsTsSymbolMapState :=
  match names with
  | List.nil => fun (state : PsTsSymbolMapState) => state
  | List.cons name rest =>
      let smaller : PsTsSymbolMapState -> PsTsSymbolMapState := psTsBuildSymbolMap namePrefix rest;
      fun (state : PsTsSymbolMapState) =>
        let fresh := psTsFreshInternal state.used namePrefix state.nextIndex;
        smaller (PsTsSymbolMapState.mk (List.cons fresh.name state.used) fresh.nextIndex
          (List.cons (Prod.mk name fresh.name) state.entriesRev))

